// Manuscript rendering engine.
//
// prepareDocument() slices the exact Markdown bytes into the API's document
// parts, then (cheaply, without KaTeX) strips front matter, comments and
// passage markers, extracts LaTeX figures, protects math, collects every
// reference definition of the whole document, parses each part with
// markdown-it and assigns document-unique fragment ids. render(i) turns one
// part's tokens into sanitised HTML and substitutes KaTeX output last.

import MarkdownIt from "markdown-it";
import type { Env, Token } from "markdown-it";
import { AnchorRegistry, byteOffsetOf, githubSlug, pandocIdentifier } from "./anchors";
import { classifyHref } from "./links";
import {
  DISPLAY_CLOSE,
  DISPLAY_OPEN,
  INLINE_CLOSE,
  INLINE_OPEN,
  protectMath,
  renderTex,
  type MathResult,
  type MathSpan,
} from "./math";
import { equationId, figureId, labelIds, linkReferences, markReferences, referenceIndex, stripRefMarks, type RefIndex, type ReferenceTable } from "./references";
import { sanitizeHtml } from "./sanitize";
import { plainNumber } from "./texBreaks";
import { clearTexBlocks, hasMarks, isMarkCode, MARK, markSource, segmentsIn, stripMarks, wrapTies, type TieSegment } from "./ties";

export { byteOffsetOf };

export interface PreparedPart {
  index: number;
  kind: "passage" | "text";
  anchor?: string;
  span: { start: number; end: number };
  /** The part's first and last source lines, counted from 1 in the document. */
  lines: { start: number; end: number };
  headings: { id: string; level: number; title: string; aliases: string[] }[];
  anchors: string[];
  figures: { key: string; caption: string; source: string }[];
  blank: boolean;
}

export interface PreparedDocument {
  stage: string;
  frontMatter: Record<string, unknown> | null;
  parts: PreparedPart[];
  anchorIndex: Map<string, number>;
  /** Number of math spans (including figure captions) across all parts. */
  mathCount: number;
  /** Non-fatal problems found while preparing (duplicate explicit ids). */
  issues: string[];
  /** Every reference definition of the document, for slices that use them (renderSlice). */
  references: NonNullable<Env["references"]>;
  /** The paper's reviewed references, once loaded: what its in-text links point to. */
  refs: RefIndex | null;
  /** The source line, from 1, that holds this byte of the document. */
  lineOfByte(byte: number): number;
  /** The first byte on a 1-based source line. */
  byteOfLine(line: number): number;
  render(index: number): RenderedPart;
  /**
   * The part's text with each formula left as its TeX source (not typeset): cheap, so every part's
   * words can be on the page from the start, where the browser's own find can reach them. The
   * typeset part (render) replaces it as the part comes near.
   */
  renderPlain(index: number): RenderedPart;
  renderAll(): RenderedPart[];
  /** Every block's words with its source line, for searching text that has not rendered yet. */
  textBlocks(): TextBlock[];
  /** The part whose front matter carries the credit line (frontCredit), or null when none does. */
  creditPart: number | null;
}

export interface TextBlock {
  part: number;
  line: number;
  text: string;
}

export interface RenderedPart {
  index: number;
  html: string;
  mathErrors: { tex: string; message: string }[];
}

export interface PrepareInput {
  stage: string;
  bytes: Uint8Array;
  parts?: { kind: string; span: { start_byte: number; end_byte: number }; passageAnchor?: string }[];
  documentPath: string;
  documentPaths: Record<string, string>;
  /** The reviewed reference table, when the paper has one. */
  referenceTable?: ReferenceTable | null;
  /** The paper's tied segments, by byte range; their spans come out in the rendered HTML. */
  ties?: readonly TieSegment[];
  /** Topic colours by tied segment, already known before the markup is emitted. */
  tieTones?: ReadonlyArray<number | undefined>;
  /**
   * What the formal development does in each section, by section number ("5.6") or heading. One is
   * set under its section's head as a reader annotation; the authors' text is not changed.
   */
  sectionAids?: Readonly<Record<string, string>> | null;
  /**
   * The paper's credit, as HTML: one short line set in the front matter, under the authors (ul.authors).
   * It is the reader's, not the authors' text, and says who wrote the paper and its Lean, where they
   * are from, and who made the links.
   */
  frontCredit?: string | null;
  /**
   * The first words of a credit note the document's own text carries (an adapted edition's "An adapted
   * edition of …"). With it, frontCredit joins the end of that note's paragraph instead of standing under
   * the authors, so the credit is said once.
   */
  frontCreditNote?: string | null;
}

// ------------------------------------------------------------- section aids

const escapeText = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

/** An aid's words as HTML: `$…$` typeset, the rest as text. */
function aidHtml(text: string): string {
  return text
    .split(/(\$[^$]+\$)/)
    .map((piece) => (piece.length > 2 && piece.startsWith("$") && piece.endsWith("$") ? renderTex(piece.slice(1, -1), false).html : escapeText(piece)))
    .join("");
}

/** Where an aid's first sentence ends: a full stop before a capital, outside any formula. */
function firstSentenceEnd(text: string): number {
  let math = false;
  for (let i = 0; i < text.length - 2; i++) {
    if (text[i] === "$") math = !math;
    else if (!math && text[i] === "." && text[i + 1] === " " && /[A-Z$]/.test(text[i + 2]) && i > 40) return i + 1;
  }
  return text.length;
}

/** The aid for a heading: by its number, by its whole title, or by its title without its number. */
export function sectionAidFor(aids: Readonly<Record<string, string>>, title: string): string | null {
  const plain = stripMarks(title).replace(/\s+/g, " ").trim();
  const number = plain.match(/^((?:\d+|[A-Z])(?:\.\d+)*)\.?(?:\s|$)/)?.[1];
  return aids[plain] ?? (number ? aids[number] : undefined) ?? aids[plain.replace(/^((?:\d+|[A-Z])(?:\.\d+)*)\.?\s+/, "")] ?? null;
}

/**
 * The annotation set under a section's head. Its first sentence shows; the rest opens in place.
 * A `<details>`, so it needs no script and nothing moves unless the reader opens it.
 */
export function sectionAidHtml(text: string): string {
  const cut = firstSentenceEnd(text);
  const lead = `<span class="section-aid__label">Formal development in this section.</span> ${aidHtml(text.slice(0, cut))}`;
  const who = `<span class="section-aid__who">Reader annotation, AI-drafted.</span>`;
  if (cut >= text.length) return `<p class="section-aid" data-aid>${lead} ${who}</p>`;
  return `<details class="section-aid" data-aid><summary>${lead} <span class="section-aid__more" aria-hidden="true"></span></summary><p>${aidHtml(text.slice(cut).trim())} ${who}</p></details>`;
}

/** A rendered part with each of its section heads followed by that section's aid. */
function withSectionAids(html: string, headings: readonly { id: string; level: number; title: string }[], aids: Readonly<Record<string, string>>): string {
  let out = html;
  for (const heading of headings) {
    // The paper's title is followed by its authors, not by a note; its aid opens the reader's "Start here".
    if (heading.level < 2) continue;
    const aid = sectionAidFor(aids, heading.title);
    if (!aid) continue;
    const at = out.indexOf(`id="${heading.id}"`);
    if (at < 0) continue;
    const close = out.slice(at).match(/<\/h[1-6]>/);
    if (!close || close.index === undefined) continue;
    const end = at + close.index + close[0].length;
    out = out.slice(0, end) + sectionAidHtml(aid) + out.slice(end);
  }
  return out;
}

// ---------------------------------------------------------------- markdown-it

interface RenderEnv extends Env {
  /** The account a fragment link belongs to, so a copy shown elsewhere can resolve it. */
  stage: string;
  documentPath: string;
  documentPaths: Record<string, string>;
  linkClose: string[];
}

const md = new MarkdownIt({ html: true, linkify: false, typographer: true });
// A print-only space request has no web content. Match only a whole line;
// Markdown's code rules run first, so literal examples remain untouched.
md.block.ruler.before("paragraph", "print_spacing", (state, startLine, _endLine, silent) => {
  if (state.sCount[startLine] - state.blkIndent >= 4) return false;
  const line = state.src.slice(state.bMarks[startLine] + state.tShift[startLine], state.eMarks[startLine]);
  const command = /^\\Needspace[ \t]*(?=\{)/.exec(line);
  if (!command) return false;
  const argument = braceGroup(line, command[0].length);
  if (!argument || line.slice(argument.end).trim()) return false;
  if (!silent) state.line = startLine + 1;
  return true;
}, { alt: ["paragraph"] });
// A tie's marks stand outside the parser's text (ties.ts). Delimiters look through them,
// so `**` opens or closes exactly as it does in the source.
const { isMdAsciiPunct, isPunctChar, isWhiteSpace } = md.utils;
const BaseInlineState = md.inline.State;
class InlineState extends BaseInlineState {
  scanDelims(start: number, canSplitWord: boolean) {
    const { src, posMax } = this as unknown as { src: string; posMax: number };
    const marker = src.charCodeAt(start);
    let before = start - 1;
    while (before >= 0 && isMarkCode(src.charCodeAt(before))) before--;
    let pos = start;
    while (pos < posMax && src.charCodeAt(pos) === marker) pos++;
    const length = pos - start;
    while (pos < posMax && isMarkCode(src.charCodeAt(pos))) pos++;
    const last = before >= 0 ? src.charCodeAt(before) : 0x20;
    const next = pos < posMax ? src.charCodeAt(pos) : 0x20;
    const lastPunct = isMdAsciiPunct(last) || isPunctChar(String.fromCharCode(last));
    const nextPunct = isMdAsciiPunct(next) || isPunctChar(String.fromCharCode(next));
    const lastSpace = isWhiteSpace(last);
    const nextSpace = isWhiteSpace(next);
    const left = !nextSpace && (!nextPunct || lastSpace || lastPunct);
    const right = !lastSpace && (!lastPunct || nextSpace || nextPunct);
    return {
      can_open: left && (canSplitWord || !right || lastPunct),
      can_close: right && (canSplitWord || !left || nextPunct),
      length,
    };
  }
}
md.inline.State = InlineState;
// Smart quotes read the neighbouring text, so each mark leaves the text tokens at once.
const MARK_SPLIT = new RegExp(`(${MARK})`);
md.core.ruler.after("inline", "tie_marks", (state) => {
  for (const block of state.tokens) {
    if (block.type !== "inline" || !block.children || !hasMarks(block.content)) continue;
    block.children = block.children.flatMap((token) => {
      if (token.type !== "text" || !hasMarks(token.content)) return [token];
      return token.content.split(MARK_SPLIT).flatMap((piece) => {
        if (!piece) return [];
        const made = new state.Token(hasMarks(piece) ? "tie_mark" : "text", "", 0);
        made.level = token.level;
        if (hasMarks(piece)) made.meta = { mark: piece };
        else made.content = piece;
        return [made];
      });
    });
  }
});
md.renderer.rules.tie_mark = (tokens, idx) => (tokens[idx].meta as { mark: string }).mark;

// Pandoc's `smart` extension converts quotes, dashes and ellipses but not
// (c), (r), (tm) or +-. Keep markdown-it's smartquotes, replace the rest.
md.disable("replacements");
md.core.ruler.after("inline", "pandoc_dashes", (state) => {
  for (const block of state.tokens) {
    if (block.type !== "inline" || !block.children) continue;
    for (const t of block.children) {
      if (t.type === "text") {
        t.content = t.content.replace(/---/g, "—").replace(/--/g, "–").replace(/\.\.\./g, "…");
      }
    }
  }
});

// Bold run-in paragraphs ("**Theorem 1 (…).**", "**Proof.**", "**Strict curvature.**").
const RUN_IN = /^(\p{Lu}[\p{L}\p{N}-]*)[^]*[.:?]$/u;
md.core.ruler.push("run_in", (state) => {
  const tokens = state.tokens;
  for (let i = 0; i + 1 < tokens.length; i++) {
    if (tokens[i].type !== "paragraph_open" || tokens[i + 1].type !== "inline") continue;
    const kids = tokens[i + 1].children ?? [];
    let k = 0;
    while (k < kids.length && (kids[k].type === "tie_mark" || (kids[k].type === "text" && kids[k].content.trim() === ""))) k++;
    if (kids[k]?.type !== "strong_open") continue;
    let text = "";
    let j = k + 1;
    for (; j < kids.length && kids[j].type !== "strong_close"; j++) text += kids[j].content;
    if (j >= kids.length) continue;
    const lead = stripRefMarks(text).trim();
    const m = RUN_IN.exec(lead);
    if (!m) continue;
    tokens[i].meta = { ...(tokens[i].meta ?? {}), lead };
    tokens[i].attrJoin("class", "run-in");
    tokens[i].attrSet("data-run-in", m[1].toLowerCase());
    kids[k].attrJoin("class", "run-in__lead");
  }
});

const esc = md.utils.escapeHtml;
const PAPER_STAGES = new Set(["long", "short", "expository"]);

md.renderer.rules.link_open = (tokens, idx, _opts, envAny) => {
  const env = envAny as unknown as RenderEnv;
  const t = tokens[idx];
  const href = String(t.attrGet("href") ?? "");
  const title = t.attrGet("title");
  const titleAttr = title ? ` title="${esc(String(title))}"` : "";
  const target = classifyHref(href, env.documentPath, env.documentPaths);
  switch (target.kind) {
    case "fragment": {
      env.linkClose.push("</a>");
      const own = PAPER_STAGES.has(env.stage) ? ` data-in="${esc(env.stage)}"` : "";
      return `<a href="${esc(target.href)}"${own}${titleAttr}>`;
    }
    case "external":
      env.linkClose.push("</a>");
      return `<a href="${esc(target.href)}" class="ext" data-external="" target="_blank" rel="noopener noreferrer"${titleAttr}>`;
    case "mailto":
      env.linkClose.push("</a>");
      return `<a href="${esc(target.href)}"${titleAttr}>`;
    case "companion":
      env.linkClose.push("</a>");
      return `<a href="${esc(target.href)}" class="companion" data-companion="${esc(target.stage)}" data-fragment="${esc(target.fragment)}"${titleAttr}>`;
    case "unresolved": {
      // A paper's link to its own figure file (`figures/x.svg`) opens the file the build serves.
      const figure = /^figures\/[\w.-]+$/.test(target.original) ? figureImageSrc(env.stage, target.original) : null;
      if (figure) {
        env.linkClose.push("</a>");
        return `<a href="${esc(figure)}" target="_blank" rel="noopener"${titleAttr}>`;
      }
      env.linkClose.push("</span>");
      return `<span class="link-unresolved" data-unresolved-href="${esc(target.original)}">`;
    }
    default:
      env.linkClose.push("</span>");
      return `<span class="link-blocked">`;
  }
};
md.renderer.rules.link_close = (_t, _i, _o, envAny) => (envAny as unknown as RenderEnv).linkClose.pop() ?? "</a>";

const defaultHeadingOpen = md.renderer.rules.heading_open;
md.renderer.rules.heading_open = (tokens, idx, opts, env, self) => {
  const aliases = (tokens[idx].meta?.aliases as string[] | undefined) ?? [];
  const pre = aliases.map((a) => `<a id="${esc(a)}" class="anchor" aria-hidden="true"></a>`).join("");
  const open = defaultHeadingOpen ? defaultHeadingOpen(tokens, idx, opts, env, self) : self.renderToken(tokens, idx, opts);
  return pre + open;
};

// ----------------------------------------------------------------- utilities

const decoder = () => new TextDecoder("utf-8", { ignoreBOM: true });

/** Minimal YAML for manuscript front matter: scalars, lists, `|` blocks. */
export function parseFrontMatter(src: string): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  const lines = src.split(/\r?\n/);
  const scalar = (v: string): unknown => {
    const s = v.trim();
    if (/^".*"$/.test(s)) {
      try {
        return JSON.parse(s);
      } catch {
        return s.slice(1, -1);
      }
    }
    if (/^'.*'$/.test(s)) return s.slice(1, -1).replace(/''/g, "'");
    if (s === "true") return true;
    if (s === "false") return false;
    if (/^-?\d+(\.\d+)?$/.test(s)) return Number(s);
    return s;
  };
  const indentOf = (l: string) => l.length - l.trimStart().length;
  for (let i = 0; i < lines.length; i++) {
    const m = /^([A-Za-z0-9_-]+):\s*(.*)$/.exec(lines[i]);
    if (!m) continue;
    const [, key, rest] = m;
    if (rest !== "" && rest !== "|" && rest !== ">") {
      out[key] = scalar(rest);
      continue;
    }
    const block: string[] = [];
    while (i + 1 < lines.length && (lines[i + 1].trim() === "" || indentOf(lines[i + 1]) > 0)) block.push(lines[++i]);
    if (rest === "|" || rest === ">") {
      out[key] = dedent(block).join(rest === "|" ? "\n" : " ");
      continue;
    }
    const items: unknown[] = [];
    for (let b = 0; b < block.length; b++) {
      const im = /^(\s*)-\s*(.*)$/.exec(block[b]);
      if (!im) continue;
      const ind = im[1].length;
      if (im[2] === "|" || im[2] === ">") {
        const body: string[] = [];
        while (b + 1 < block.length && (block[b + 1].trim() === "" || indentOf(block[b + 1]) > ind)) body.push(block[++b]);
        items.push(dedent(body).join("\n").replace(/\n+$/, ""));
      } else items.push(scalar(im[2]));
    }
    out[key] = items;
  }
  return out;
}

function dedent(lines: string[]): string[] {
  const ind = Math.min(...lines.filter((l) => l.trim()).map((l) => l.length - l.trimStart().length));
  return lines.map((l) => l.slice(Number.isFinite(ind) ? ind : 0));
}

/** Synchronous SHA-256 (hex) of a string's UTF-8 bytes. */
export function sha256Hex(text: string): string {
  const K = new Uint32Array([
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98,
    0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
    0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8,
    0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819,
    0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
    0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
    0xc67178f2,
  ]);
  const data = new TextEncoder().encode(text);
  const bitLen = data.length * 8;
  const padded = new Uint8Array(((data.length + 9 + 63) >> 6) << 6);
  padded.set(data);
  padded[data.length] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(padded.length - 8, Math.floor(bitLen / 0x100000000));
  view.setUint32(padded.length - 4, bitLen >>> 0);
  const H = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const W = new Uint32Array(64);
  const rotr = (x: number, n: number) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < padded.length; off += 64) {
    for (let t = 0; t < 16; t++) W[t] = view.getUint32(off + t * 4);
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      const s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + W[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + t1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) >>> 0;
    }
    H[0] += a; H[1] += b; H[2] += c; H[3] += d; H[4] += e; H[5] += f; H[6] += g; H[7] += h;
  }
  return Array.from(H, (x) => x.toString(16).padStart(8, "0")).join("");
}

// ------------------------------------------------------------------- figures

/** Read a balanced `{…}` group starting at `open` (index of `{`). */
function braceGroup(s: string, open: number): { body: string; end: number } | null {
  if (s[open] !== "{") return null;
  let depth = 0;
  for (let i = open; i < s.length; i++) {
    const c = s[i];
    if (c === "\\") {
      i++;
      continue;
    }
    if (c === "{") depth++;
    else if (c === "}" && --depth === 0) return { body: s.slice(open + 1, i), end: i + 1 };
  }
  return null;
}

function commandArg(s: string, name: string): { body: string; start: number; end: number } | null {
  const at = s.indexOf(`\\${name}{`);
  if (at < 0) return null;
  const g = braceGroup(s, at + name.length + 1);
  return g ? { body: g.body, start: at, end: g.end } : null;
}

function stripTexComments(s: string): string {
  return s
    .split("\n")
    .map((l) => l.replace(/(^|[^\\])%.*$/, "$1"))
    .join("\n");
}

/** Caption TeX to HTML (math left as placeholders) and to plain text. */
function convertCaption(tex: string, spans: MathSpan[]): { html: string; plain: string } {
  const { text } = protectMath(tex.replace(/\s+/g, " ").trim(), spans);
  const walk = (s: string, asHtml: boolean): string => {
    let out = "";
    for (let i = 0; i < s.length; i++) {
      const c = s[i];
      if (c === "\\") {
        const m = /^\\([A-Za-z]+|.)/.exec(s.slice(i));
        const name = m ? m[1] : "";
        if (name === "href") {
          const u = braceGroup(s, i + 5);
          const t = u ? braceGroup(s, u.end) : null;
          if (u && t) {
            const inner = walk(t.body, asHtml);
            if (asHtml && /^https?:\/\//i.test(u.body.trim())) {
              out += `<a href="${esc(u.body.trim())}" class="ext" data-external="" target="_blank" rel="noopener noreferrer">${inner}</a>`;
            } else out += inner;
            i = t.end - 1;
            continue;
          }
        }
        if (name === "emph" || name === "textit" || name === "textbf" || name === "text") {
          const g = braceGroup(s, i + 1 + name.length);
          if (g) {
            const inner = walk(g.body, asHtml);
            const tag = name === "textbf" ? "strong" : name === "text" ? "" : "em";
            out += asHtml && tag ? `<${tag}>${inner}</${tag}>` : inner;
            i = g.end - 1;
            continue;
          }
        }
        if (name.length === 1 && "%&#_$ {}".includes(name)) {
          out += asHtml ? esc(name) : name;
          i += 1;
          continue;
        }
        if (name === "\\") {
          out += asHtml ? "<br>" : " ";
          i += 1;
          continue;
        }
        // Unknown command: keep it visible rather than dropping text.
        out += asHtml ? esc(`\\${name}`) : `\\${name}`;
        i += name.length;
        continue;
      }
      if (c === "{" || c === "}") continue;
      if (c === "~") {
        out += " ";
        continue;
      }
      if (s.startsWith("---", i)) {
        out += "—";
        i += 2;
        continue;
      }
      if (s.startsWith("--", i)) {
        out += "–";
        i += 1;
        continue;
      }
      if (s.startsWith("``", i)) {
        out += "“";
        i += 1;
        continue;
      }
      if (s.startsWith("''", i)) {
        out += "”";
        i += 1;
        continue;
      }
      out += asHtml ? esc(c) : c;
    }
    return out;
  };
  const html = walk(text, true);
  const plain = walk(text, false).replace(
    new RegExp(`[${INLINE_OPEN}${DISPLAY_OPEN}](\\d+)[${INLINE_CLOSE}${DISPLAY_CLOSE}]`, "g"),
    (_m, n: string) => spans[Number(n)]?.tex ?? "",
  );
  return { html, plain };
}

interface FigureInfo {
  key: string;
  caption: string;
  source: string;
  captionHtml: string;
  /** The image file a figure shows (`\\includegraphics{figures/x.svg}`), where it is a picture rather than TikZ. */
  image: string | null;
}

/**
 * Where a paper's figure file is served: the build copies papers/<name>/<stage>/figures/
 * to paper-figures/<stage>/ (vite.config.ts). Only the file's own name is used, so a
 * figure can name no other path.
 */
export function figureImageSrc(stage: string, path: string): string | null {
  const name = path.trim().split("/").pop() ?? "";
  if (!/^[\w.-]+\.(svg|png|jpe?g|webp)$/i.test(name)) return null;
  const base = (import.meta.env?.BASE_URL as string | undefined) ?? "/";
  return `${base}paper-figures/${stage}/${name}`;
}

const FIG_OPEN = "";
const FIG_CLOSE = "";

/**
 * Figure KEY rule (stable; React figure components are keyed by it):
 *   the `\label{…}` value inside the figure when present, otherwise
 *   `fig-` + the first 10 hex characters of SHA-256 over the figure source
 *   from `\begin{figure}` to `\end{figure}` inclusive, with every run of
 *   whitespace collapsed to one space and the ends trimmed.
 */
export function figureKey(figureEnv: string): string {
  const label = commandArg(stripTexComments(figureEnv), "label");
  if (label && label.body.trim()) return label.body.trim();
  return "fig-" + sha256Hex(figureEnv.replace(/\s+/g, " ").trim()).slice(0, 10);
}

function parseFigure(env: string, spans: MathSpan[]): FigureInfo {
  const clean = stripTexComments(env);
  const tikz = /\\begin\{tikzpicture\}[\s\S]*?\\end\{tikzpicture\}/.exec(env);
  let captionTex = commandArg(clean, "caption")?.body ?? "";
  captionTex = captionTex.replace(/\\label\{[^}]*\}/g, "");
  const { html, plain } = convertCaption(captionTex, spans);
  const image = tikz ? null : (/\\includegraphics(?:\[[^\]]*\])?\{([^}]+)\}/.exec(clean)?.[1] ?? null);
  return { key: figureKey(env), caption: plain, source: tikz ? tikz[0] : env, captionHtml: html, image };
}

const FIGURE_ENV = /\\begin\{figure\*?\}(?:\[[^\]]*\])?[\s\S]*?\\end\{figure\*?\}/g;

function extractFigures(src: string, figures: FigureInfo[], spans: MathSpan[]): string {
  const mark = (env: string) => {
    figures.push(parseFigure(env, spans));
    return `\n\n${FIG_OPEN}${figures.length - 1}${FIG_CLOSE}\n\n`;
  };
  // Fenced raw LaTeX (```{=latex}): figures become slots, anything else is
  // dropped, as Pandoc drops raw LaTeX when writing HTML.
  let out = src.replace(/^(`{3,}|~{3,})[ \t]*\{=latex\}[^\n]*\n([\s\S]*?)^\1[ \t]*$/gm, (_m, _f, body: string) => {
    const envs = body.match(FIGURE_ENV) ?? [];
    return envs.map(mark).join("");
  });
  // Unfenced figure environments (Pandoc raw_tex blocks).
  out = out.replace(new RegExp(`^[ \\t]*${FIGURE_ENV.source}[ \\t]*$`, "gm"), (env) => mark(env.trim()));
  return out;
}

// ---------------------------------------------------------------- preparation

interface PartState {
  tokens: Token[];
  spans: MathSpan[];
  figures: FigureInfo[];
  /** Figures before this part, for their numbers. */
  figuresBefore: number;
  rendered?: RenderedPart;
}

function preprocess(text: string, atStart: boolean, frontMatter: { value: Record<string, unknown> | null }): string {
  let src = text;
  if (atStart) {
    const fm = /^---[ \t]*\r?\n([\s\S]*?)\r?\n(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/.exec(src);
    if (fm) {
      frontMatter.value = parseFrontMatter(fm[1]);
      src = src.slice(fm[0].length);
    }
  }
  // Match each comment through its first closer. Drop the line only if the
  // comment occupies it entirely, so a page marker followed by prose keeps it.
  src = src.replace(/(^[ \t]*)?<!--[\s\S]*?-->([ \t]*(?:\r?\n|$))?/gm,
    (_comment, indent: string | undefined, tail: string | undefined) =>
      indent !== undefined && tail !== undefined ? "" : (indent ?? "") + (tail ?? ""));
  // PDF-only wrappers around companion links: keep the inner Markdown link.
  src = src.replace(/<span\s+class="pdf-companion"[^>]*>([\s\S]*?)<\/span>/g, "$1");
  // Explicit bookmarks.
  src = src.replace(/<a\s+id="([^"]+)"\s*>\s*<\/a>/g, '<a id="$1" class="anchor" aria-hidden="true"></a>');
  return src;
}

const REF_DEF = /^ {0,3}\[(?:[^\]\\\n]|\\.)+\]:[ \t]*\S.*$/gm;

/**
 * A paper's own table of contents ("Contents", with its table of sections and pages) is left out of
 * the reading copy: the contents column beside the paper lists the same sections, live. Only the
 * heading and the tables under it go; an anchor or anything else before the next heading stays.
 */
function dropContents(states: PartState[], parts: PreparedPart[]): void {
  let dropping = false;
  for (const [index, st] of states.entries()) {
    const kept: Token[] = [];
    for (let i = 0; i < st.tokens.length; i++) {
      const t = st.tokens[i];
      if (t.type === "heading_open") {
        const title = t.tag === "h1" || t.tag === "h2" ? inlineText(st.tokens[i + 1]?.children ?? [], st.spans).trim() : "";
        if (/^(table of )?contents$/i.test(title) && st.tokens[i + 2]?.type === "heading_close") {
          dropping = true;
          i += 2;
          continue;
        }
        dropping = false;
      } else if (dropping) {
        if (t.type === "table_open") {
          while (i < st.tokens.length && st.tokens[i].type !== "table_close") i++;
          continue;
        }
        if (!(t.type === "html_block" && /^\s*<!--[\s\S]*?-->\s*$/.test(t.content))) dropping = false;
      }
      kept.push(t);
    }
    if (kept.length !== st.tokens.length) {
      st.tokens = kept;
      // A removed heading or table can occupy a whole source part. Keep its
      // source position, but reserve no space when nothing remains to display.
      if (kept.length === 0) parts[index].blank = true;
    }
  }
}

function inlineText(children: Token[], spans: MathSpan[]): string {
  let s = "";
  for (const c of children) {
    if (c.type === "text" || c.type === "code_inline") s += stripMarks(c.content);
    else if (c.type === "softbreak" || c.type === "hardbreak") s += " ";
  }
  return s.replace(new RegExp(`[${INLINE_OPEN}${DISPLAY_OPEN}](\\d+)[${INLINE_CLOSE}${DISPLAY_CLOSE}]`, "g"), (_m, n: string) => spans[Number(n)]?.tex ?? "");
}

/** One part's tokens as sanitised HTML, with KaTeX output substituted last. */
/** The start of every line of a document's bytes, for byte-to-line lookups. */
function lineStarts(bytes: Uint8Array): number[] {
  const starts = [0];
  for (let i = 0; i < bytes.length; i++) if (bytes[i] === 10) starts.push(i + 1);
  return starts;
}

function lineAt(starts: number[], byte: number): number {
  let lo = 0;
  let hi = starts.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (starts[mid] <= byte) lo = mid;
    else hi = mid - 1;
  }
  return lo + 1;
}

const LINE_ATTR = `(?: data-line="(\\d+)")?`;
/** Any tie marks at this place, kept: a block built around a formula leaves them outside it. */
const MARKS = `(${MARK}*)`;
const LITERAL_BREAK = new RegExp(`[${INLINE_OPEN}${DISPLAY_OPEN}${FIG_OPEN}]\\d+[${INLINE_CLOSE}${DISPLAY_CLOSE}${FIG_CLOSE}]`, "g");
const LONE_MATH = new RegExp(`^\\s*${DISPLAY_OPEN}(\\d+)${DISPLAY_CLOSE}`);

/** A piece of a processed line that also stands in the raw text: the formula of a display, else its longest run of words. */
function literalOf(line: string, spans: MathSpan[]): string {
  const display = LONE_MATH.exec(line);
  if (display) return spans[Number(display[1])]?.tex.split("\n").find((l) => l.trim())?.trim() ?? "";
  const best = line.split(LITERAL_BREAK).reduce((a, b) => (b.trim().length > a.length ? b.trim() : a), "");
  return best.length >= 4 ? best : "";
}

/**
 * Stamp each block with its line in the source (data-line). Preparing a part drops
 * comment lines and folds multi-line formulas, so token maps count lines of the
 * processed text; each block is found again in the raw text, in order, by its words
 * or formula. A block with neither (a figure) takes the next line that has text.
 */
function stampLines(tokens: Token[], text: string, rawText: string, spans: MathSpan[], firstLine: number): void {
  const processed = stripMarks(text).split("\n");
  const raw = rawText.split("\n");
  let cursor = 0;
  for (const token of tokens) {
    if (!token.map || token.nesting < 0 || token.type === "inline") continue;
    const literal = literalOf(processed[token.map[0]] ?? "", spans);
    let found = -1;
    if (literal) for (let i = cursor; i < raw.length && found < 0; i++) if (raw[i].includes(literal)) found = i;
    if (found < 0) {
      found = cursor;
      while (found < raw.length - 1 && (!raw[found].trim() || raw[found].trimStart().startsWith("<!--"))) found++;
    }
    token.attrSet("data-line", String(firstLine + found));
    // A list or quotation shares its first line with the block inside it.
    cursor = /^(bullet_list|ordered_list|list_item|blockquote)/.test(token.type) ? found : found + 1;
  }
}

function renderTokens(
  st: PartState,
  env: RenderEnv,
  typesetSpan: (span: MathSpan) => MathResult,
  /** The whole paper's references; a slice has none, and no ids, since the original stands elsewhere. */
  refs?: { index: RefIndex | null; tieTones?: ReadonlyArray<number | undefined> },
): { html: string; mathErrors: { tex: string; message: string }[] } {
  let html = md.renderer.render(st.tokens, md.options, env);
  const equationAttr = (n: string) => {
    const id = refs ? equationId(st.spans[Number(n)]?.tex ?? "") : null;
    return id ? ` id="${esc(id)}"` : "";
  };
  html = html.replace(new RegExp(`<p${LINE_ATTR}>${MARKS}${FIG_OPEN}(\\d+)${FIG_CLOSE}${MARKS}</p>`, "g"), (_m, line: string | undefined, before: string, n: string, after: string) => {
    const f = st.figures[Number(n)];
    const key = esc(f.key);
    const id = refs ? ` id="${figureId(st.figuresBefore + Number(n) + 1)}"` : "";
    const src = f.image ? figureImageSrc(env.stage, f.image) : null;
    return `${before}<figure class="paper-figure"${id}${line ? ` data-line="${line}"` : ""} data-figure="${key}"><div class="paper-figure__art" data-figure-slot="${key}"${src ? ` data-figure-image="${esc(src)}"` : ""}></div><figcaption>${f.captionHtml}</figcaption></figure>${after}`;
  });
  // A paragraph that is only a Markdown image (`![caption](figures/x.svg)`) is a figure: the
  // slot shows the file (reader/mount.tsx) and the caption is the image's title, else its text.
  if (html.includes("<img")) {
    html = html.replace(/<p( data-line="\d+")?>\s*<img src="([^"]*)" alt="([^"]*)"(?: title="([^"]*)")?\s*\/?>\s*<\/p>/g, (whole, line: string | undefined, path: string, alt: string, title: string | undefined) => {
      const src = figureImageSrc(env.stage, path.replace(/&amp;/g, "&"));
      if (!src) return whole;
      const key = esc(`img:${src.split("/").pop()}`);
      // A bare label ("Figure 1") as alt text is not a caption: the paper's own caption paragraph
      // follows the image, so repeating the label under the picture would show it twice.
      const caption = title ?? (/^(?:figure|fig\.?)\s*[\w.-]+\.?$/i.test(alt.trim()) ? "" : alt);
      return `<figure class="paper-figure paper-figure--image"${line ?? ""} data-figure="${key}"><div class="paper-figure__art" data-figure-slot="${key}" data-figure-image="${esc(src)}" data-figure-alt="${alt}"></div>${caption ? `<figcaption>${caption}</figcaption>` : ""}</figure>`;
    });
  }
  html = sanitizeHtml(html);
  if (refs) html = linkReferences(html, refs.index);
  html = html.replace(new RegExp(`<p(?: data-line="\\d+")?>${MARKS}((?:\\s*<a [^>]*class="anchor"[^>]*></a>)+)\\s*${MARKS}</p>`, "g"), "$1$2$3");
  const mathErrors: { tex: string; message: string }[] = [];
  const typeset = (n: string) => {
    const span = st.spans[Number(n)];
    if (!span) return "";
    const r = typesetSpan(span);
    if (r.error) mathErrors.push({ tex: span.tex, message: r.error });
    return r.html;
  };
  // A display with one plain equation number carries it as its own element beside the formula
  // from the start (PaperBody.tsx, formsFor), so fitting never changes its layout after it paints.
  const display = (n: string) => {
    const html = typeset(n);
    const number = plainNumber(st.spans[Number(n)]?.tex ?? "");
    // KaTeX marks a display's one number katex-tag (and each row's number in an environment, tag).
    if (!number || (html.match(/class="(katex-tag|tag)"/g) ?? []).length !== 1) return { attr: "", html };
    return { attr: ' data-number=""', html: `${html}<span class="katex math-number">${esc(number)}</span>` };
  };
  html = html.replace(
    new RegExp(`<p${LINE_ATTR}>${MARKS}${DISPLAY_OPEN}(\\d+)${DISPLAY_CLOSE}${MARKS}</p>`, "g"),
    (_m, line: string | undefined, before: string, n: string, after: string) => {
      const d = display(n);
      return `${before}<div class="math-display"${equationAttr(n)}${line ? ` data-line="${line}"` : ""}${d.attr}>${d.html}</div>${after}`;
    },
  );
  html = html.replace(new RegExp(`${DISPLAY_OPEN}(\\d+)${DISPLAY_CLOSE}`, "g"), (_m, n: string) => {
    const d = display(n);
    return `<span class="math-display"${equationAttr(n)}${d.attr}>${d.html}</span>`;
  });
  // Punctuation directly after inline math stays on the formula's line.
  html = html.replace(
    new RegExp(`${INLINE_OPEN}(\\d+)${INLINE_CLOSE}${MARKS}([.,;:!?)\\]\u2019\u201d]+)?`, "g"),
    // Chrome breaks after KaTeX's last box despite the wrapper, so a short
    // formula is kept whole; a long one may still break between relations.
    (_m, n: string, marks: string, punct?: string) => {
      if (!punct) return typeset(n) + marks;
      const whole = (st.spans[Number(n)]?.tex.length ?? 0) <= 48 ? " math-nobreak--whole" : "";
      return `<span class="math-nobreak${whole}">${typeset(n)}${marks}${punct}</span>`;
    },
  );
  return { html: wrapTies(html, undefined, refs?.tieTones), mathErrors };
}

export interface SliceInput {
  stage: string;
  documentPath: string;
  documentPaths: Record<string, string>;
  /** The paper's reference definitions, once it is loaded. Without them a reference link shows its words alone. */
  references?: NonNullable<Env["references"]>;
}

const REFERENCE_LINK = /\[((?:[^[\]\\]|\\.)*)\]\[((?:[^[\]\\]|\\.)*)\]/g;

/** Whether a Markdown slice uses a reference-style link, whose definition lives elsewhere in its paper. */
export function hasReferenceLink(markdown: string): boolean {
  REFERENCE_LINK.lastIndex = 0;
  return REFERENCE_LINK.test(markdown);
}

/**
 * A slice of a paper's Markdown through the same pipeline as a whole part, so it is
 * typeset exactly as the paper is. A reference link with no definition to hand shows
 * its visible words, never its brackets. Slices are short, so repeats are the caller's
 * to cache; formulas are shared across slices here.
 */
export function renderSlice(markdown: string, input: SliceInput): RenderedPart {
  const references = input.references ?? {};
  const spans: MathSpan[] = [];
  const figures: FigureInfo[] = [];
  const withFigures = extractFigures(preprocess(markdown, false, { value: null }), figures, spans);
  const { text } = protectMath(withFigures, spans);
  const linked = text.replace(REFERENCE_LINK, (whole, label: string, key: string) =>
    references[md.utils.normalizeReference(key || label)] ? whole : label,
  );
  const tokens = md.parse(linked, { references });
  const env: RenderEnv = { references, stage: input.stage, documentPath: input.documentPath, documentPaths: input.documentPaths, linkClose: [] };
  return { index: -1, ...renderTokens({ tokens, spans, figures, figuresBefore: 0 }, env, typesetShared) };
}

const sliceMath = new Map<string, MathResult>();

function typesetShared(span: MathSpan): MathResult {
  const key = `${span.display ? "display" : "inline"}:${span.tex}`;
  let result = sliceMath.get(key);
  if (result) sliceMath.delete(key);
  else result = renderTex(span.tex, span.display);
  sliceMath.set(key, result);
  if (sliceMath.size > 512) sliceMath.delete(sliceMath.keys().next().value!);
  return result;
}

export function prepareDocument(input: PrepareInput): PreparedDocument {
  const { bytes } = input;
  const dec = decoder();
  const starts = lineStarts(bytes);
  const lineOfByte = (byte: number) => lineAt(starts, byte);
  const partSpecs = input.parts?.length
    ? input.parts
    : [{ kind: "unmapped_text", span: { start_byte: 0, end_byte: bytes.length } }];

  const refs = input.referenceTable ? referenceIndex(input.referenceTable, bytes) : null;
  const frontMatter = { value: null as Record<string, unknown> | null };
  const sources: string[] = [];
  const raw: string[] = [];
  // What is parsed carries the tie marks. `raw` and every comparison made on it stay the source.
  const marked: string[] = [];
  const decode = (piece: Uint8Array) => dec.decode(piece);
  for (const p of partSpecs) {
    const text = dec.decode(bytes.subarray(p.span.start_byte, p.span.end_byte));
    raw.push(text);
    sources.push(preprocess(text, p.span.start_byte === 0, frontMatter));
    const span = { start: p.span.start_byte, end: p.span.end_byte };
    const inside = input.ties ? segmentsIn(input.ties, span.start, span.end) : [];
    const tied = inside.length ? clearTexBlocks(markSource(bytes, span, inside, decode)) : text;
    // Reference marks go in over the tie marks, which stand for no bytes.
    const linked = markReferences(tied, span.start, refs);
    marked.push(linked === text ? sources[sources.length - 1] : preprocess(linked, span.start === 0, { value: null }));
  }

  // Reference definitions from the whole document, available to every part.
  const references: NonNullable<Env["references"]> = {};
  const defs = sources.flatMap((s) => s.match(REF_DEF) ?? []);
  if (defs.length) md.parse(defs.join("\n\n"), { references });

  const registry = new AnchorRegistry();
  const states: PartState[] = [];
  const parts: PreparedPart[] = [];
  let mathCount = 0;

  let figuresBefore = 0;

  // Pass 1: figures, math, parse, explicit anchors.
  marked.forEach((src0, index) => {
    const spans: MathSpan[] = [];
    const figures: FigureInfo[] = [];
    const withFigures = extractFigures(src0, figures, spans);
    const { text } = protectMath(withFigures, spans);
    // A mark that a slice left inside a formula must not reach KaTeX.
    for (const span of spans) span.tex = stripMarks(span.tex);
    const tokens = md.parse(text, { references });
    stampLines(tokens, stripRefMarks(text), raw[index], spans, lineOfByte(partSpecs[index].span.start_byte));
    states.push({ tokens, spans, figures, figuresBefore });
    mathCount += spans.length;
    const spec = partSpecs[index];
    const kind = spec.kind === "mapped_passage" ? "passage" : "text";
    const anchor = spec.passageAnchor ?? (kind === "passage" ? /<!--\s*passage:([^\s>]+)\s*-->/.exec(raw[index])?.[1] : undefined);
    const anchors: string[] = [];
    for (const m of text.matchAll(/<a id="([^"]+)" class="anchor"/g)) {
      if (registry.claimExplicit(m[1], index)) anchors.push(m[1]);
    }
    // Numbered equations and figures are addresses too.
    for (const span of spans) {
      const id = equationId(span.tex);
      if (id && registry.claimExplicit(id, index)) anchors.push(id);
    }
    figures.forEach((_f, n) => {
      const id = figureId(figuresBefore + n + 1);
      if (registry.claimExplicit(id, index)) anchors.push(id);
    });
    figuresBefore += figures.length;
    parts.push({
      index,
      kind,
      ...(anchor ? { anchor } : {}),
      span: { start: spec.span.start_byte, end: spec.span.end_byte },
      lines: { start: lineOfByte(spec.span.start_byte), end: lineOfByte(Math.max(spec.span.start_byte, spec.span.end_byte - 1)) },
      headings: [],
      anchors,
      figures: figures.map(({ key, caption, source }) => ({ key, caption, source })),
      blank: raw[index].trim() === "",
    });
  });

  dropContents(states, parts);

  // Pass 2: label and heading ids in document order.
  const labelId = labelIds();
  states.forEach((st, index) => {
    const part = parts[index];
    for (let i = 0; i < st.tokens.length; i++) {
      const t = st.tokens[i];
      if (t.type === "paragraph_open" && t.meta?.lead) {
        const id = labelId(t.meta.lead as string);
        if (id && registry.claimExplicit(id, index)) {
          t.attrSet("id", id);
          part.anchors.push(id);
        }
      }
      if (t.type !== "heading_open") continue;
      const inline = st.tokens[i + 1];
      const title = inlineText(inline?.children ?? [], st.spans).trim();
      const id = registry.claimHeading(pandocIdentifier(title), index);
      t.attrSet("id", id);
      t.attrs?.sort((x, y) => Number(y[0] === "id") - Number(x[0] === "id"));
      const aliases: string[] = [];
      const gh = githubSlug(title);
      if (gh !== id && registry.claimAlias(gh, index)) aliases.push(gh);
      t.meta = { ...(t.meta ?? {}), aliases };
      // A bookmark-only paragraph immediately before a heading names that
      // section too. Keep the existing bookmark in place; only its association
      // is added here, so comparison panes can find the section's passage.
      const before = st.tokens[i - 1]?.type === "paragraph_close"
        && st.tokens[i - 2]?.type === "inline" && st.tokens[i - 3]?.type === "paragraph_open"
        ? stripMarks(st.tokens[i - 2].content) : "";
      const bookmark = /<a id="([^"]+)" class="anchor" aria-hidden="true"><\/a>/g;
      const explicit = before.replace(bookmark, "").trim() === ""
        ? [...before.matchAll(bookmark)].map((match) => match[1]).filter((anchor) => registry.partOf(anchor) === index)
        : [];
      part.headings.push({ id, level: Number(t.tag.slice(1)), title, aliases: [...aliases, ...explicit] });
      part.anchors.push(id, ...aliases);
    }
  });

  // The credit line goes under the authors' names in the front matter, in the part that lists them.
  // An adapted edition's own credit note takes the line at the end of its paragraph instead.
  const fold = (text: string) => text.replace(/[’‘]/g, "'").replace(/\s+/g, " ");
  const note = input.frontCredit && input.frontCreditNote ? fold(input.frontCreditNote) : null;
  const authorsAt = input.frontCredit && !note ? raw.findIndex((text) => /<ul class="authors">[\s\S]*?<\/ul>/.test(text)) : -1;
  const noteAt = note ? raw.findIndex((text) => fold(text).includes(note)) : -1;
  const creditPart = authorsAt >= 0 ? authorsAt : noteAt >= 0 ? noteAt : null;
  const withCredit = (index: number, html: string) => {
    if (index !== creditPart || !input.frontCredit) return html;
    if (!note) return html.replace(/<ul class="authors">[\s\S]*?<\/ul>/, (list) => `${list}\n<p class="front-credit">${input.frontCredit}</p>`);
    const at = fold(html).indexOf(note) >= 0 ? html.search(new RegExp(note.split(" ").map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("\\s+").replace(/'/g, "['’‘]"))) : -1;
    const open = at >= 0 ? html.lastIndexOf("<p", at) : -1;
    const close = at >= 0 ? html.indexOf("</p>", at) : -1;
    // The edition's long note gives way to its one short line (the whole credit is in About). Where the
    // note's words cannot be found in the drawn paragraph, the line still stands, after the part.
    if (open < 0 || close < 0) return `${html}\n<p class="front-credit">${input.frontCredit}</p>`;
    return `${html.slice(0, open)}<p class="front-credit front-credit--edition">${input.frontCredit}</p>${html.slice(close + 4)}`;
  };

  const anchorIndex = registry.entries();
  const issues = registry.duplicates.map((d) => `duplicate explicit id "${d.id}" in parts ${d.parts[0]} and ${d.parts[1]}`);

  // Inline symbols recur throughout a paper. Keep a bounded cache on this
  // prepared document, so later parts can reuse exactly the same KaTeX output
  // without retaining an unbounded second copy of every unique formula.
  const mathCache = new Map<string, MathResult>();
  const typesetSpan = (span: MathSpan): MathResult => {
    const key = `${span.display ? "display" : "inline"}:${span.tex}`;
    let result = mathCache.get(key);
    if (result) mathCache.delete(key);
    else result = renderTex(span.tex, span.display);
    mathCache.set(key, result);
    if (mathCache.size > 256) mathCache.delete(mathCache.keys().next().value!);
    return result;
  };

  let blocks: TextBlock[] | undefined;
  const render = (index: number): RenderedPart => {
    const st = states[index];
    if (!st) throw new RangeError(`no part ${index}`);
    if (st.rendered) return st.rendered;
    const env: RenderEnv = {
      references,
      stage: input.stage,
      documentPath: input.documentPath,
      documentPaths: input.documentPaths,
      linkClose: [],
    };
    const made = renderTokens(st, env, typesetSpan, { index: refs, tieTones: input.tieTones });
    const headings = parts[index]?.headings ?? [];
    st.rendered = { index, ...made, html: withCredit(index, input.sectionAids && headings.length ? withSectionAids(made.html, headings, input.sectionAids) : made.html) };
    return st.rendered;
  };

  const plainSpan = (span: MathSpan): MathResult => ({
    html: `<span class="math-pending" data-display="${span.display}">${esc(span.tex)}</span>`,
  });
  const plainParts = new Map<number, RenderedPart>();
  const renderPlain = (index: number): RenderedPart => {
    const st = states[index];
    if (!st) throw new RangeError(`no part ${index}`);
    if (st.rendered) return st.rendered;
    let done = plainParts.get(index);
    if (!done) {
      const env: RenderEnv = { references, stage: input.stage, documentPath: input.documentPath, documentPaths: input.documentPaths, linkClose: [] };
      const made = renderTokens(st, env, plainSpan, { index: refs, tieTones: input.tieTones });
      done = { index, ...made, html: withCredit(index, made.html) };
      plainParts.set(index, done);
    }
    return done;
  };

  return {
    stage: input.stage,
    frontMatter: frontMatter.value,
    parts,
    anchorIndex,
    mathCount,
    issues,
    references,
    refs,
    lineOfByte,
    byteOfLine: (line) => starts[Math.max(0, Math.min(starts.length - 1, line - 1))],
    render,
    renderPlain,
    renderAll: () => parts.map((p) => render(p.index)),
    creditPart,
    textBlocks: () =>
      (blocks ??= states.flatMap((st, part) =>
        st.tokens.flatMap((token, i) => {
          if (token.type !== "inline") return [];
          const line = Number(st.tokens[i - 1]?.attrGet("data-line") ?? parts[part].lines.start);
          const text = stripRefMarks(inlineText(token.children ?? [], st.spans)).replace(/\s+/g, " ").trim();
          return text ? [{ part, line, text }] : [];
        }),
      )),
  };
}
